import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines

class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_count_and_hours(self):
        shifts = [
            Shift("Odell", "mon", Span(540, 735)),
            Shift("Odell", "tue", Span(800, 995)),
            Shift("Brisa", "mon", Span(540, 1020)),
            Shift("Brisa", "tue", Span(540, 1020))
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 16.0 hours",
                "Odell: 2 shifts, 6.5 hours"
            ]
        )

    def test_equal_hours_sorted_by_name(self):
        shifts = [
            Shift("Zed", "mon", Span(540, 600)),
            Shift("Amira", "mon", Span(540, 600))
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Amira: 1 shifts, 1.0 hours",
                "Zed: 1 shifts, 1.0 hours"
            ]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            with self.subTest(name=name):
                span = Span(540, 600)
                shifts = [Shift(name, "mon", span)]
                with self.assertRaises(ValueError):
                    timesheet_lines(shifts)
